def seed_work_gallery(apps, schema_editor):
    WorkCategory = apps.get_model("catalog", "WorkCategory")
    WorkItem = apps.get_model("catalog", "WorkItem")
    WorkItemImage = apps.get_model("catalog", "WorkItemImage")
    PageSection = apps.get_model("catalog", "PageSection")
    NavItem = apps.get_model("catalog", "NavItem")

    PageSection.objects.update_or_create(
        key="gallery",
        defaults={
            "section_id": "gallery",
            "eyebrow": "Галерея робіт",
            "title": "Різні варіанти —",
            "title_emphasis": "під вашу кімнату.",
            "subtitle": (
                "Оберіть тип меблів і відкрийте картку: "
                "кілька фото і те, чим цей варіант відрізняється."
            ),
            "is_visible": True,
            "order": 2,
        },
    )
    projects = PageSection.objects.filter(key="projects").first()
    if projects and projects.cta_href in ("", "#projects"):
        projects.cta_href = "#gallery"
        if not projects.cta_text:
            projects.cta_text = "Всі проєкти →"
        projects.save(update_fields=["cta_href", "cta_text"])

    if not NavItem.objects.filter(href="#gallery").exists():
        header = list(
            NavItem.objects.filter(location="header", order__gte=2).order_by("-order", "-id")
        )
        for item in header:
            item.order += 1
            item.save(update_fields=["order"])
        NavItem.objects.create(
            label="Галерея",
            href="#gallery",
            location="header",
            order=2,
            is_visible=True,
        )

    if WorkCategory.objects.exists():
        return

    from catalog.work_gallery import create_work_gallery

    create_work_gallery(WorkCategory, WorkItem, WorkItemImage)


def unseed_work_gallery(apps, schema_editor):
    WorkCategory = apps.get_model("catalog", "WorkCategory")
    PageSection = apps.get_model("catalog", "PageSection")
    NavItem = apps.get_model("catalog", "NavItem")
    WorkCategory.objects.all().delete()
    PageSection.objects.filter(key="gallery").delete()
    NavItem.objects.filter(href="#gallery", location="header").delete()
    projects = PageSection.objects.filter(key="projects", cta_href="#gallery").first()
    if projects:
        projects.cta_href = "#projects"
        projects.save(update_fields=["cta_href"])


